export const getCompanyTypeIcon = (type) => {
    switch (type?.toLowerCase()) {
        case 'переработчик':
            return (
                <img
                    src={'https://cdn.jsdelivr.net/gh/TWhirly/slidors-app@master/src/icons/recycler.png'}
                    alt="переработчик"
                    fill="#008ad1"
                    className={styles.factoryIcon}
                />
            );
        case 'дистрибьютор':
            return (
                <img
                    src={'https://cdn.jsdelivr.net/gh/TWhirly/slidors-app@master/src/icons/distributor.png'}
                    alt="дистрибьютор"
                    fill="#008ad1"
                    className={styles.factoryIcon}
                />
            );
        case 'дилер':
            return (
                <img
                    src={'https://cdn.jsdelivr.net/gh/TWhirly/slidors-app@master/src/icons/dealer.png'}
                    alt="Дилер"
                    fill="#008ad1"
                    className={styles.factoryIcon}
                />
            );
        case 'смешанный':
            return (
                <img
                    src={'https://cdn.jsdelivr.net/gh/TWhirly/slidors-app@master/src/icons/mixed.png'}
                    alt="Смешанный"
                    fill="#008ad1"
                    className={styles.factoryIcon}
                />
            );
        case 'избранный':
            return <YellowStarIcon className={styles.factoryIcon} />;
        default:
            return <></>;
    }
};

export const getStatusColor = (status) => {
    if (status.toLowerCase().includes('уточнить'))
        return 'orange';
    switch (status?.toLowerCase()) {
        case 'работает':
            return 'lightgreen';
        case 'не работает':
            return 'var(--hintColor, #888)';
        case 'уточнить тел.':
            return 'orange';
        default:
            return 'var(--hintColor, #888)';
    }
};

