// import '../src/css/theme.css';
import * as React from 'react';
import { useNavigate, Routes, Route } from 'react-router-dom';
import { useEffect } from "react";
import { useTelegram } from "./hooks/useTelegram";
import Header from "./components/Header/Header";
import Main from "./components/Main/Main";
import { DataProvider } from './DataContext.jsx';
import Companies from './components/Companies/Companies';
import CompanyDetails from './components/Companies/CompanyDetails';
import ContactDetails from './components/Contacts/ContactDetails';
import CompanyEditForm from './components/Companies/CompanyEditForm';
import EmptyComponent from './components/Companies/EmptyComponent';
import ContactEditForm from './components/Contacts/ContactEditForm';
import Activities from './components/Activity/Activities.jsx';
import ActivityDetails from './components/Activity/ActivityDetails';
import ActivityEditForm from './components/Activity/ActivityEditForm';
import Contacts from './components/Contacts/Contacts';
import Subscribes from './components/Companies/Subscribes.jsx';
import ReportsMenu from './components/Reports/ReportsMenu.jsx';
import SnvManager from './components/Reports/SnvManager.jsx';
import SubscribesReport from './components/Reports/SubscribesReport.jsx';
import DailyReport from './components/Reports/DailyReport.jsx';
import { NotificationProvider } from './components/notifications/NotificationContext.jsx';

function App() {

  // const queryClient = new QueryClient({
  //   defaultOptions: {
  //     queries: {
  //       staleTime: 1000 * 60 * 5, // 5 минут данные не считаются "протухшими"
  //       refetchOnWindowFocus: false, // Важно для TMA, чтобы не спамить при открытии
  //     },
  //   },
  // });


  // eslint-disable-next-line no-unused-vars
  // const { showNotification } = useNotification();
  const navigate = useNavigate();
  const { tg } = useTelegram();
  const hasHandledInitialNavigation = React.useRef(false);
  // window.Telegram.WebApp.expand();
  window.Telegram.WebApp.disableVerticalSwipes()
  // console.log('init param ', window.Telegram.WebApp)
  tg.MainButton.hide()
  tg.MainButton.setParams({
    text: `Отправить`
  })
  //  React.useEffect(() => {
  //     const tg = window.Telegram.WebApp;
  //       tg.BackButton.hide();
  //     }, [navigate])

  // if (window.Telegram.WebApp.colorScheme === 'dark') {
  document.documentElement.style.setProperty("--bgColor", "#000000");

  // }
  // else {
  //     document.documentElement.style.setProperty("--bgColor", "#ffffff");
  //     tg.setHeaderColor("#ffffff")
  // }
  // console.log('scheme', window.Telegram.WebApp.colorScheme)

  useEffect(() => {
    tg.ready();
    const fontFamily = tg.platform === 'desktop' ? 'Open Sans, sans-serif' : 'system-ui, sans-serif';
    const textColor = '#ffffff';

    document.documentElement.style.setProperty('--fontFamily', fontFamily);
    document.documentElement.style.setProperty('--textColor', textColor);

    document.body.style.fontFamily = fontFamily;
    window.Telegram.WebApp.exitFullscreen();
    document.body.style.color = textColor;
    tg.setHeaderColor("#131313");
    tg.setBackgroundColor("#131313");
  }, [tg])

  useEffect(() => {
    if (hasHandledInitialNavigation.current) return;
    hasHandledInitialNavigation.current = true;

    // Обработка Telegram WebApp параметров
    if (window.Telegram?.WebApp?.initData) {
      // const path = urlParams.get('tgWebAppStartParam') || '/';
      // console.log('tg params', path)

      // Перенаправляем на корректный путь
      navigate('/');
    }
  }, [navigate]);

  return (
    // <QueryClientProvider client={queryClient}>
    <NotificationProvider>
      <DataProvider>
        <div className="App">
          <Header />
          <Routes>
            <Route path="/" element={<Main />} />
            <Route path="/companies" element={<Companies />} />
            <Route path="/subscribes" element={<Subscribes />} />
            <Route path="/contacts" element={<Contacts />} />
            <Route path="/companies/:id" element={<CompanyDetails />} />
            <Route path="/companies/:id/edit" element={<CompanyEditForm />} />
            <Route path="/contacts/:id/edit" element={<ContactEditForm />} />
            <Route path="/activities/:id/edit" element={<ActivityEditForm />} />
            <Route path="/contacts/:id" element={<ContactDetails />} />
            <Route path="/activities" element={<Activities />} />
            <Route path="/activities/:id" element={<ActivityDetails />} />
            <Route path="/empty/" element={<EmptyComponent />} />
            <Route path="/reports" element={<ReportsMenu />} />
            <Route path="/reports/snvManager" element={<SnvManager />} />
            <Route path="/reports/subscribesReport" element={<SubscribesReport />} />
            <Route path="/reports/dailyReport" element={<DailyReport />} />
          </Routes>
        </div>
      </DataProvider>
    </NotificationProvider>
    // </QueryClientProvider>
  );
}



export default App
